namespace pcl
{

inline IsoString PSCMIconSVG()
{
   static const char svg[] = R"PSCM_ICON(<?xml version="1.0" encoding="UTF-8"?><svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="128" height="128" viewBox="0 0 128 128"><image width="128" height="128" preserveAspectRatio="xMidYMid meet" xlink:href="data:image/png;base64,"/></svg>)PSCM_ICON";
   return IsoString( svg );
}

} // namespace pcl